index de9b0cd..1a0c4a3 100644
--- a/src/nextorm.core/DataContext/QueryExecutor.cs
+++ b/src/nextorm.core/DataContext/QueryExecutor.cs
@@ -439,6 +439,46 @@ internal sealed class QueryExecutor : IQueryExecutor, IRowReaderFactory
         }
     }

+    /// <summary>
+    /// Opens a buffered <see cref="DbDataReader"/> over a prepared query command for a consumer that
+    /// reads the raw result columns (the CSV terminals). Unlike <see cref="OpenLobReader{TResult}"/> the
+    /// reader is not opened with sequential access, so it works on every relational provider and never
+    /// appends a LOB locator column. The caller disposes only the reader; the prepared command stays
+    /// owned by the plan cache.
+    /// </summary>
+    /// <typeparam name="TResult">The projected result type; it is not materialised on this path.</typeparam>
+    /// <param name="preparedQueryCommand">The prepared command to execute.</param>
+    /// <param name="params">The positional parameter values bound to the query.</param>
+    /// <returns>The opened reader.</returns>
+    internal DbDataReader OpenRawReader<TResult>(IPreparedQueryCommand<TResult> preparedQueryCommand, ReadOnlySpan<object?> @params)
+    {
+        var compiledQuery = AsDbCommand(preparedQueryCommand);
+        if (compiledQuery.PendingBatch is not null)
+            throw new NotSupportedException(RawReaderBatchNotSupported);
+
+        var command = GetDbCommand(compiledQuery, @params);
+        return RunReader(command, compiledQuery.Behavior);
+    }
+
+    /// <summary>Asynchronously opens a buffered reader over a prepared query command. See <see cref="OpenRawReader{TResult}"/>.</summary>
+    /// <typeparam name="TResult">The projected result type; it is not materialised on this path.</typeparam>
+    /// <param name="preparedQueryCommand">The prepared command to execute.</param>
+    /// <param name="params">The positional parameter values bound to the query, or <see langword="null"/>.</param>
+    /// <param name="cancellationToken">Cancels opening the reader.</param>
+    /// <returns>A task producing the opened reader.</returns>
+    internal async Task<DbDataReader> OpenRawReaderAsync<TResult>(IPreparedQueryCommand<TResult> preparedQueryCommand, object[]? @params, CancellationToken cancellationToken)
+    {
+        var compiledQuery = AsDbCommand(preparedQueryCommand);
+        if (compiledQuery.PendingBatch is not null)
+            throw new NotSupportedException(RawReaderBatchNotSupported);
+
+        var command = await GetDbCommand(compiledQuery, @params, cancellationToken).ConfigureAwait(false);
+        return await RunReaderAsync(command, compiledQuery.Behavior, cancellationToken).ConfigureAwait(false);
+    }
+
+    private const string RawReaderBatchNotSupported =
+        "A raw-column read (CSV streaming) is not supported for a temporary-table source; materialise the source into a table first.";
+
     /// <summary>Executes a mutation and returns the number of affected rows.</summary>
     /// <param name="sql">The parameterised statement text.</param>
     /// <param name="parameters">The parameters referenced by <paramref name="sql"/>.</param>

