private static readonly System.Text.UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

/// <summary>
/// Executes the command and writes the result set as CSV to <paramref name="stream"/>. Rows are read
/// straight from the provider reader and written through typed accessors, so no <typeparamref name="TResult"/>
/// is created per row and the standard column types are not boxed. The stream is left open.
/// </summary>
/// <typeparam name="TResult">The projected result type; it is not materialised on this path.</typeparam>
/// <param name="command">The command to execute.</param>
/// <param name="stream">The destination stream; it is not closed or disposed by this call.</param>
/// <param name="options">The CSV formatting options, or <see langword="null"/> for <see cref="CsvOptions.Default"/>.</param>
/// <param name="parameters">The positional parameter values bound to the query.</param>
/// <returns>The number of rows written (the header line is not counted).</returns>
public static long ToCsv<TResult>(this QueryCommand<TResult> command, Stream stream, CsvOptions? options = null, params ReadOnlySpan<object?> parameters)
{
    ArgumentNullException.ThrowIfNull(command);
    ArgumentNullException.ThrowIfNull(stream);

    using var writer = new StreamWriter(stream, Utf8NoBom, 1024, leaveOpen: true);
    return WriteCsv(command, writer, options ?? CsvOptions.Default, parameters);
}

/// <summary>
/// Executes the command and writes the result set as CSV to <paramref name="writer"/>. Rows are read
/// straight from the provider reader and written through typed accessors, so no <typeparamref name="TResult"/>
/// is created per row and the standard column types are not boxed. The writer is flushed but not disposed.
/// </summary>
/// <typeparam name="TResult">The projected result type; it is not materialised on this path.</typeparam>
/// <param name="command">The command to execute.</param>
/// <param name="writer">The destination writer; it is flushed but not disposed by this call.</param>
/// <param name="options">The CSV formatting options, or <see langword="null"/> for <see cref="CsvOptions.Default"/>.</param>
/// <param name="parameters">The positional parameter values bound to the query.</param>
/// <returns>The number of rows written (the header line is not counted).</returns>
public static long ToCsv<TResult>(this QueryCommand<TResult> command, TextWriter writer, CsvOptions? options = null, params ReadOnlySpan<object?> parameters)
{
    ArgumentNullException.ThrowIfNull(command);
    ArgumentNullException.ThrowIfNull(writer);

    return WriteCsv(command, writer, options ?? CsvOptions.Default, parameters);
}

/// <summary>
/// Asynchronously executes the command and writes the result set as CSV to <paramref name="stream"/>.
/// Rows are read straight from the provider reader and written through typed accessors, so no
/// <typeparamref name="TResult"/> is created per row and the standard column types are not boxed.
/// The stream is left open.
/// </summary>
/// <typeparam name="TResult">The projected result type; it is not materialised on this path.</typeparam>
/// <param name="command">The command to execute.</param>
/// <param name="stream">The destination stream; it is not closed or disposed by this call.</param>
/// <param name="options">The CSV formatting options, or <see langword="null"/> for <see cref="CsvOptions.Default"/>.</param>
/// <param name="cancellationToken">Cancels opening the reader and reading rows.</param>
/// <param name="parameters">The positional parameter values bound to the query.</param>
/// <returns>A task producing the number of rows written (the header line is not counted).</returns>
public static async Task<long> ToCsvAsync<TResult>(this QueryCommand<TResult> command, Stream stream, CsvOptions? options = null, CancellationToken cancellationToken = default, params object[] parameters)
{
    ArgumentNullException.ThrowIfNull(command);
    ArgumentNullException.ThrowIfNull(stream);

    var writer = new StreamWriter(stream, Utf8NoBom, 1024, leaveOpen: true);
    using (writer)
    {
        return await WriteCsvAsync(command, writer, options ?? CsvOptions.Default, parameters, cancellationToken).ConfigureAwait(false);
    }
}

/// <summary>
/// Asynchronously executes the command and writes the result set as CSV to <paramref name="writer"/>.
/// Rows are read straight from the provider reader and written through typed accessors, so no
/// <typeparamref name="TResult"/> is created per row and the standard column types are not boxed.
/// The writer is flushed but not disposed.
/// </summary>
/// <typeparam name="TResult">The projected result type; it is not materialised on this path.</typeparam>
/// <param name="command">The command to execute.</param>
/// <param name="writer">The destination writer; it is flushed but not disposed by this call.</param>
/// <param name="options">The CSV formatting options, or <see langword="null"/> for <see cref="CsvOptions.Default"/>.</param>
/// <param name="cancellationToken">Cancels opening the reader and reading rows.</param>
/// <param name="parameters">The positional parameter values bound to the query.</param>
/// <returns>A task producing the number of rows written (the header line is not counted).</returns>
public static async Task<long> ToCsvAsync<TResult>(this QueryCommand<TResult> command, TextWriter writer, CsvOptions? options = null, CancellationToken cancellationToken = default, params object[] parameters)
{
    ArgumentNullException.ThrowIfNull(command);
    ArgumentNullException.ThrowIfNull(writer);

    return await WriteCsvAsync(command, writer, options ?? CsvOptions.Default, parameters, cancellationToken).ConfigureAwait(false);
}

private static long WriteCsv<TResult>(QueryCommand<TResult> command, TextWriter writer, CsvOptions options, ReadOnlySpan<object?> parameters)
{
    var context = RequireRelationalContext(command);
    var prepared = context.GetPreparedRawColumnsCommand(command, CancellationToken.None);

    using var reader = context.OpenRawReader(prepared, parameters);
    var csv = new CsvWriter(writer, options);

    if (options.IncludeHeader)
        csv.WriteHeader(reader);

    long rows = 0;
    while (reader.Read())
    {
        csv.WriteRow(reader);
        rows++;
    }

    csv.Flush();
    writer.Flush();
    return rows;
}

private static async Task<long> WriteCsvAsync<TResult>(QueryCommand<TResult> command, TextWriter writer, CsvOptions options, object[] parameters, CancellationToken cancellationToken)
{
    var context = RequireRelationalContext(command);
    var prepared = context.GetPreparedRawColumnsCommand(command, cancellationToken);

    using var reader = await context.OpenRawReaderAsync(prepared, parameters, cancellationToken).ConfigureAwait(false);
    var csv = new CsvWriter(writer, options);

    if (options.IncludeHeader)
        csv.WriteHeader(reader);

    long rows = 0;
    while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
    {
        csv.WriteRow(reader);
        rows++;
    }

    csv.Flush();
    await writer.FlushAsync(cancellationToken).ConfigureAwait(false);
    return rows;
}

internal const string LobDataReaderLocatorMessage =
    "ToDataReader is not supported on providers that append a LOB locator column (SQLite); use ToStream/ToTextReader for a single LOB column.";

private const string LobProjectionMessageLeavingLocatorHint =
    "ToStream/ToTextReader require a projection with exactly one byte[] or string column; read several columns with ToDataReader instead.";

private const string LobProjectionMessageLocatorDialect =
    "ToStream/ToTextReader require a projection with exactly one byte[] or string column.";

// The general reader needs the same sequential-access capability as the single-column terminals, but
// it cannot expose a dialect locator column, so it is narrower than they are: SQLite (which appends
// rowid) and the providers without sequential access both fail closed before opening the reader.
private static void EnsureDataReaderSupported(DataContext context)
{
    if (!context.Dialect.SupportsSequentialAccess)
        throw new NotSupportedException(
            $"ToDataReader is not supported by the {context.Dialect.GetType().Name} provider; it requires sequential-access support (PostgreSQL or SQL Server).");

    if (context.Dialect.LobLocatorColumn is not null)
        throw new NotSupportedException(LobDataReaderLocatorMessage);
}

private static string LobProjectionMessage(DataContext context)
    => context.Dialect.LobLocatorColumn is null
        ? LobProjectionMessageLeavingLocatorHint
        : LobProjectionMessageLocatorDialect;

private const string RawSqlLocatorMessage =
    "SQLite LOB streaming with raw SQL (WithSql) is not supported because a rowid locator cannot be added safely.";

// A LOB projection is one user column plus an optional trailing dialect locator (SQLite's rowid)
// that makes the driver stream the payload. Two user columns exceed this count and are still
// rejected, because the locator is appended only by the dialect on the streaming path. A raw SQL
// override (WithSql/PrepareFromSql) bypasses the SQL builder entirely, so no locator is appended
// for it: on a locator dialect there is no safe way to stream an arbitrary single-column raw
// projection, so that shape is rejected outright; every other raw shape keeps the generic
// projection-mismatch error.
private static void EnsureLobFieldCount(CommandReaderOwner owner, DataContext context, QueryCommand command)
{
    if (context.Dialect.LobLocatorColumn is not null && command.CustomData is RawSqlOverride)
    {
        if (owner.Reader.FieldCount == 1)
            throw new NotSupportedException(RawSqlLocatorMessage);

        throw new InvalidOperationException(LobProjectionMessage(context));
    }

    var expectedFieldCount = context.Dialect.LobLocatorColumn is null ? 1 : 2;
    if (owner.Reader.FieldCount != expectedFieldCount)
        throw new InvalidOperationException(LobProjectionMessage(context));
}

private static DataContext RequireRelationalContext(QueryCommand command)
{
    ThrowIfDisposed(command.DataContext);

    return command.DataContext as DataContext
        ?? throw new NotSupportedException(
            "LOB reads require a database provider; the in-memory provider has no DbDataReader and supports only the single-column ToStream/ToTextReader terminals.");
}

private static void ThrowIfDisposed(IDataContext? context)
{
    var disposed = context switch
    {
        DataContext db => db.IsDisposed,
        InMemoryDataContext memory => memory.IsDisposed,
        _ => false,
    };

    ObjectDisposedException.ThrowIf(disposed, nameof(DataContext));
}

